  "road.badge": { en: "ROADMAP", es: "ROADMAP", fr: "FEUILLE DE ROUTE", pt: "ROTEIRO", de: "ROADMAP", zh: "\u8def\u7ebf\u56fe", ar: "\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642", th: "\u0e41\u0e1c\u0e19\u0e07\u0e32\u0e19" },
  "road.desc": { en: "Progressive development of the QFS ecosystem through strategic phases, from the base infrastructure to global digital finance.", es: "Desarrollo progresivo del ecosistema QFS a trav\u00e9s de fases estrat\u00e9gicas, desde la infraestructura base hasta las finanzas digitales globales.", fr: "D\u00e9veloppement progressif de l'\u00e9cosyst\u00e8me QFS \u00e0 travers des phases strat\u00e9giques, de l'infrastructure de base \u00e0 la finance num\u00e9rique mondiale.", pt: "Desenvolvimento progressivo do ecossistema QFS atrav\u00e9s de fases estrat\u00e9gicas, da infraestrutura b\u00e1s \u00e0s finan\u00e7as digitais globais.", de: "Progressive Entwicklung des QFS-\u00d6kosystems durch strategische Phasen, von der Basisinfrastruktur bis zur globalen digitalen Finanzierung.", zh: "\u901a\u8fc7\u6218\u7565\u9636\u6bb5\u9010\u6b65\u5f00\u53d1QFS\u751f\u6001\u7cfb\u7edf\uff0c\u4ece\u57fa\u7840\u8bbe\u65bd\u5230\u5168\u7403\u6570\u5b57\u91d1\u878d\u3002", ar: "\u0627\u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a \u0644\u0646\u0638\u0627\u0645 QFS \u0639\u0628\u0631 \u0645\u0631\u0627\u062d\u0644 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629\u060c \u0645\u0646 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0631\u0642\u0645\u064a \u0627\u0644\u0639\u0627\u0644\u0645\u064a.", th: "\u0e01\u0e32\u0e23\u0e1e\u0e31\u0e12\u0e19\u0e32\u0e23\u0e30\u0e1a\u0e1a\u0e19\u0e34\u0e40\u0e27\u0e28 QFS \u0e2d\u0e22\u0e48\u0e32\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e31\u0e49\u0e19\u0e15\u0e2d\u0e19\u0e1c\u0e48\u0e32\u0e19\u0e0a\u0e48\u0e27\u0e07\u0e40\u0e27\u0e25\u0e32\u0e17\u0e32\u0e07\u0e22\u0e38\u0e17\u0e18\u0e28\u0e32\u0e2a\u0e15\u0e23\u0e4c \u0e15\u0e31\u0e49\u0e07\u0e41\u0e15\u0e48\u0e42\u0e04\u0e23\u0e07\u0e2a\u0e23\u0e49\u0e32\u0e07\u0e1e\u0e37\u0e49\u0e19\u0e10\u0e32\u0e19\u0e08\u0e19\u0e16\u0e36\u0e07\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25\u0e23\u0e30\u0e14\u0e31\u0e1a\u0e42\u0e25\u0e01" },
  "road.eco.desc": { en: "An interconnected suite of financial services powered by quantum technology.", es: "Una suite interconectada de servicios financieros impulsada por tecnolog\u00eda cu\u00e1ntica.", fr: "Une suite interconnect\u00e9e de services financiers aliment\u00e9e par la technologie quantique.", pt: "Um conjunto interconectado de servi\u00e7os financeiros impulsionado por tecnologia qu\u00e2ntica.", de: "Eine verbundene Suite von Finanzdienstleistungen, angetrieben von Quantentechnologie.", zh: "\u7531\u91cf\u5b50\u6280\u672f\u9a71\u52a8\u7684\u4e92\u8054\u91d1\u878d\u670d\u52a1\u5957\u4ef6\u3002", ar: "\u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u062a\u0631\u0627\u0628\u0637\u0629 \u0645\u0646 \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0645\u062f\u0639\u0648\u0645\u0629 \u0628\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0643\u0645.", th: "\u0e0a\u0e38\u0e14\u0e1a\u0e23\u0e34\u0e01\u0e32\u0e23\u0e17\u0e32\u0e07\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e17\u0e35\u0e48\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e21\u0e15\u0e48\u0e2d\u0e01\u0e31\u0e19\u0e42\u0e14\u0e22\u0e02\u0e31\u0e1a\u0e40\u0e04\u0e25\u0e37\u0e48\u0e2d\u0e19\u0e14\u0e49\u0e27\u0e22\u0e40\u0e17\u0e04\u0e42\u0e19\u0e42\u0e25\u0e22\u0e35\u0e04\u0e27\u0e2d\u0e19\u0e15\u0e31\u0e21" },
  "road.eco.dev": { en: "In Development", es: "En Desarrollo", fr: "En D\u00e9veloppement", pt: "Em Desenvolvimento", de: "In Entwicklung", zh: "\u5f00\u53d1\u4e2d", ar: "\u0642\u064a\u062f \u0627\u0644\u062a\u0637\u0648\u064a\u0631", th: "\u0e2d\u0e22\u0e39\u0e48\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\u0e1e\u0e31\u0e12\u0e19\u0e32" },
