  "road.eco.soon": { en: "Coming Soon", es: "Pr\u00f3ximamente", fr: "Prochainement", pt: "Em Breve", de: "Demn\u00e4chst", zh: "\u5373\u5c06\u63a8\u51fa", ar: "\u0642\u0631\u064a\u0628\u0627\u064b", th: "\u0e40\u0e23\u0e47\u0e27\u0e46 \u0e19\u0e35\u0e49" },
  "road.eco.subtitle": { en: "Ecosystem Map", es: "Mapa del Ecosistema", fr: "Carte de l'\u00c9cosyst\u00e8me", pt: "Mapa do Ecossistema", de: "\u00d6kosystem-Karte", zh: "\u751f\u6001\u7cfb\u7edf\u56fe", ar: "\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0646\u0638\u0627\u0645", th: "\u0e41\u0e1c\u0e19\u0e17\u0e35\u0e48\u0e23\u0e30\u0e1a\u0e1a\u0e19\u0e34\u0e40\u0e27\u0e28" },
  "road.phases": { en: "Development Phases", es: "Fases de Desarrollo", fr: "Phases de D\u00e9veloppement", pt: "Fases de Desenvolvimento", de: "Entwicklungsphasen", zh: "\u5f00\u53d1\u9636\u6bb5", ar: "\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u0637\u0648\u064a\u0631", th: "\u0e0a\u0e48\u0e27\u0e07\u0e01\u0e32\u0e23\u0e1e\u0e31\u0e12\u0e19\u0e32" },
