  "why.access.desc": { en: "Financial services accessible from an integrated platform.", es: "Servicios financieros accesibles desde una plataforma integrada.", fr: "Services financiers accessibles depuis une plateforme int\u00e9gr\u00e9e.", pt: "Servi\u00e7os financeiros acess\u00edveis de uma plataforma integrada.", de: "Finanzdienstleistungen zug\u00e4nglich \u00fcber eine integrierte Plattform.", zh: "\u901a\u8fc7\u96c6\u6210\u5e73\u53f0\u5373\u53ef\u8bbf\u95ee\u7684\u91d1\u878d\u670d\u52a1\u3002", ar: "\u062e\u062f\u0645\u0627\u062a \u0645\u0627\u0644\u064a\u0629 \u0645\u062a\u0627\u062d\u0629 \u0645\u0646 \u0645\u0646\u0635\u0629 \u0645\u062a\u0643\u0627\u0645\u0644\u0629.", th: "\u0e1a\u0e23\u0e34\u0e01\u0e32\u0e23\u0e17\u0e32\u0e07\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e17\u0e35\u0e48\u0e40\u0e02\u0e49\u0e32\u0e16\u0e36\u0e07\u0e44\u0e14\u0e49\u0e08\u0e32\u0e01\u0e41\u0e1e\u0e25\u0e15\u0e1f\u0e2d\u0e23\u0e4c\u0e21\u0e1a\u0e39\u0e23\u0e13\u0e32\u0e01\u0e32\u0e23" },
