  "why.security.desc": { en: "Infrastructure designed with security as absolute priority.", es: "Infraestructura dise\u00f1ada con seguridad como prioridad absoluta.", fr: "Infrastructure con\u00e7ue avec la s\u00e9curit\u00e9 comme priorit\u00e9 absolue.", pt: "Infraestrutura projetada com seguran\u00e7a como prioridade absoluta.", de: "Infrastruktur mit Sicherheit als absolutem Priorit\u00e4t.", zh: "\u4ee5\u5b89\u5168\u4e3a\u7edd\u5bf9\u4f18\u5148\u4e8b\u9879\u8bbe\u8ba1\u7684\u57fa\u7840\u8bbe\u65bd\u3002", ar: "\u0628\u0646\u064a\u0629 \u062a\u062d\u062a\u064a\u0627 \u0627\u0644\u0623\u0645\u0627\u0646 \u0643\u0623\u0648\u0644\u0648\u064a\u0629 \u0645\u0637\u0644\u0642\u0629.", th: "\u0e42\u0e04\u0e23\u0e07\u0e2a\u0e23\u0e49\u0e32\u0e07\u0e1e\u0e37\u0e49\u0e19\u0e10\u0e32\u0e19\u0e17\u0e35\u0e48\u0e2d\u0e2d\u0e01\u0e41\u0e1a\u0e1a\u0e42\u0e14\u0e22\u0e43\u0e2b\u0e49\u0e04\u0e27\u0e32\u0e21\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22\u0e40\u0e1b\u0e47\u0e19\u0e2d\u0e31\u0e19\u0e14\u0e31\u0e1a\u0e2b\u0e19\u0e36\u0e48\u0e07" },
  "why.speed": { en: "Speed", es: "Velocidad", fr: "Vitesse", pt: "Velocidade", de: "Geschwindigkeit", zh: "\u901f\u5ea6", ar: "\u0627\u0644\u0633\u0631\u0639\u0629", th: "\u0e04\u0e27\u0e32\u0e21\u0e40\u0e23\u0e47\u0e27" },
