  "portal.pay.feat1.desc": { en: "Military-grade quantum encryption protects every transaction from hacking and fraud.", es: "Cifrado cuántico de grado militar protege cada transacción contra piratería y fraude.", fr: "Le chiffrement quantique de niveau militaire protège chaque transaction contre le piratage et la fraude.", pt: "Criptografia quântica de nível militar protege cada transação contra hacking e fraude.", de: "Militärische Quantenverschlüsselung schützt jede Transaktion vor Hackern und Betrug.", zh: "军事级量子加密保护每笔交易免受黑客和欺诈.", ar: "تشفير كمي عسكري المستوى يحمي كل معاملة من الاختراق والاحتيال.", th: "การเข้ารหัสควอนตัมระดับทางทหารกรักษาป้องการณ์ทุกแบบการ์" },
  "portal.pay.feat2.title": { en: "Global Acceptance", es: "Aceptación Global", fr: "Acceptation Mondiale", pt: "Aceitação Global", de: "Globale Akzeptanz", zh: "全球接受", ar: "قبول عالمي", th: "การยอมรับทั่วโลก" },
  "portal.pay.feat2.desc": { en: "Accepted by all G20 nations and participating merchants worldwide.", es: "Aceptado por todas las naciones del G20 y comerciantes participantes en todo el mundo.", fr: "Accepté par toutes les nations du G20 et les marchands participants dans le monde.", pt: "Aceito por todas as nações do G20 e comerciantes participantes em todo o mundo.", de: "Akzeptiert von allen G20-Nationen und teilnehmenden Händlern weltweit.", zh: "全球G20国家和参与商户均可接受.", ar: "مقبول من جميع دول المجمع الثلاثي والتجار المشاركين في العالم.", th: "ได้รับการยอมรับประเทศ G20 ทุกประเทศ และผู้ค้าที่เข้าร่วมทั่วโลก" },
  "portal.pay.feat3.title": { en: "Instant Settlement", es: "Liquidación Instantánea", fr: "Règlement Instantané", pt: "Liquidação Instantânea", de: "Sofortige Abwicklung", zh: "即时结算", ar: "تسوية فورية", th: "การชำระเงินทันที" },
  "portal.pay.feat3.desc": { en: "Transactions complete in quantum time with no banking delays.", es: "Las transacciones se completan en tiempo cuántico sin retrasos bancarios.", fr: "Les transactions se complètent en temps quantique sans délais bancaires.", pt: "As transações são concluídas em tempo quântico sem atrasos bancários.", de: "Transaktionen werden in Quantenzeit ohne Bankverzögerungen abgeschlossen.", zh: "交易在量子时间内完成，无银行延迟.", ar: "تتم المعاملات في الوقت الكمي بدون تأخير مصرفي.", th: "ธุรการ์เสร็จสมบูรณ์ในเวลาควอนตัม โดยไม่มีความชักช้าทางธนาคาร" },
